methods.example:
const p = part('Wedge').sketch('front', (s) => s.rect(40, 40)).extrude(10);
p.workplane('front', 10, { rotate: { axis: 'x', angle: 30 } });
const tilted = p.handle();
p.sketch(at(tilted), (s) => s.circle(8)).extrude(6);

// t.y is [0, 0, -1]: a point at sketch y = 10 on the top plane is at world z = -10
const p = plane('top').toWorld([5, 10], 20);   // [5, 20, -10]
part('Offset ring').sketch('top', (s) => s.circle(4, [5, 10])).extrude(2).expectBBox({ min: [1, 0, -14], max: [9, 2, -6] });

part('Angle').sheetRules({ name: 'S2', thickness: 2 })
  .sketch('front', (s) => { s.line([0, 0], [0, 20]); s.line([0, 20], [30, 20]); })
  .contourFlange({ distance: 40, rule: 'S2' });

part('Tray').sheetRules({ name: 'S2', thickness: 2, bendRadius: 2 })
  .sketch('front', (s) => s.rect(100, 60)).baseFlange()
  .edgeFlange([[50, 0, 2], [50, 60, 2], [0, 30, 2], [100, 30, 2]], { height: 15 });

part('Fold').sheetRules({ name: 'S2', thickness: 2 })
  .sketch('front', (s) => s.rect(100, 60)).baseFlange()
  .fold({ points: [[40, 0, 2], [40, 60, 2]], angle: 60 });

part('Cone').loft([
  { on: 'front', draw: (s) => s.circle(10) },
  { on: at('front', 30), point: [0, 0] },
], { ends: { last: 'point' } });

part('Plate').sheetRules({ name: 'S2', thickness: 2 })
  .sketch('front', (s) => s.rect(100, 60)).baseFlange()
  .sheetCorner([[50, 30, 2], [-50, 30, 2]], { mode: 'round', radius: 5 });

part('Pipe').sweep(
  { on: 'front', draw: (s) => { s.circle(5); s.circle(4); } },
  { on: 'right', draw: (s) => s.polyline([[0, 0], [0, 40], [20, 60]]) },
);

part('Tapped block').sketch('front', (s) => s.rect(30, 30)).extrude(20)
  .hole(face('>Z'), [0, 0], { diameter: 5, depth: 12 })
  .thread('hole', { size: 'M6', length: 10 });

part('Plate').sketch('front', (s) => s.rect(60, 40)).extrude(12)
  .hole(face('>Z'), [-15, 0], { diameter: 8 })
  .hole(face('>Z'), [15, 0], { kind: 'cbore', diameter: 6.6, cboreDiameter: 11, cboreDepth: 6 });

part('Grid plate').sketch('front', (s) => s.rect(80, 60)).extrude(10)
  .sketch(face('>Z'), (s) => s.circle(3, [-30, -20])).cut(through())
  .linearPattern({ count: 4, to: face('>X'), toOffset: -10, direction: 'x', second: { direction: 'y', count: 3, totalLength: 40 } });

part('Rail').sketch('front', (s) => s.rect(100, 60)).extrude(5)
  .sketch(face('>Z'), (s) => s.circle(2, [-40, -20])).cut(through())
  .pathPattern({ path: { on: 'front', draw: (s) => s.polyline([[-40, -20], [40, -20], [40, 20]]) }, count: 7, totalLength: 120 });

const doc = { format: 'ck-part', version: 1, name: 'Plate', features: [], seq: 1, rollback: null };
part('Stack').insertPart(doc, { fixed: true }).insertPart(doc, { at: [0, 0, 30] })
  .mate({ kind: 'coincident', a: { part: 1, face: 'F2.C1' }, b: { part: 2, face: 'F2.C0' } });

p.sketch('front', (s) => s.circle([0, 0], 30)).extrude(3);
const lens = p.handle();
p.appearance({ feature: lens, colour: '#b9c7d6', opacity: 0.18, finish: 'glass' });
p.appearance({ face: lens, only: ['C0', 'C1'], colour: '#222222' });   // just the two end caps of that feature

const p = part('Plate').sketch('front', (s) => s.rect(60, 40)).extrude(10);
p.sketch(face('>Z'), (s) => s.circle(12)).extrude(15);
const boss = p.handle();
p.hole(face('>Z', { of: boss }), [0, 0], { diameter: 8 });

const p = part('Plate');
const m = await p.textMetrics('SEA SPRITE', { font: 'engrave', height: 5 });
p.sketch('front', (s) => s.rect(m.width + 8, 12)).extrude(2);

const p = part('Block').sketch('front', (s) => s.rect(40, 30)).extrude(20);
const v = await p.volume();   // 24000
p.expectVolume(v, { tol: 1e-6 });
